ALTER TABLE "app"."autolaris_payment" ADD CONSTRAINT "autolaris_payment_value_check" CHECK ("app"."autolaris_payment"."environment" IN ('local','test','production') AND "app"."autolaris_payment"."reff_id" ~ '^[A-Za-z0-9_-]{8,64}$' AND "app"."autolaris_payment"."channel_code" ~ '^[A-Z0-9_]{2,20}$' AND "app"."autolaris_payment"."requested_amount" between 1 and 9007199254740991
  AND (("app"."autolaris_payment"."responded_at" IS NULL AND "app"."autolaris_payment"."trx_id" IS NULL AND "app"."autolaris_payment"."instruction_kind" IS NULL AND "app"."autolaris_payment"."instruction_value" IS NULL AND "app"."autolaris_payment"."provider_amount" IS NULL AND "app"."autolaris_payment"."admin_fee" IS NULL AND "app"."autolaris_payment"."provider_total" IS NULL AND "app"."autolaris_payment"."refusal_code" IS NULL)
   OR ("app"."autolaris_payment"."responded_at" IS NOT NULL AND "app"."autolaris_payment"."operation_id" IS NOT NULL AND "app"."autolaris_payment"."trx_id" ~ '^[A-Za-z0-9_-]{1,64}$' AND "app"."autolaris_payment"."instruction_kind" IN ('virtual_account','qr','payment_code','url') AND char_length("app"."autolaris_payment"."instruction_value") between 1 and 2048
    AND "app"."autolaris_payment"."provider_amount" between 1 and 9007199254740991 AND "app"."autolaris_payment"."admin_fee" between 0 and 9007199254740991 AND "app"."autolaris_payment"."provider_total" between 1 and 9007199254740991
    AND ("app"."autolaris_payment"."refusal_code" IS NULL OR "app"."autolaris_payment"."refusal_code" IN ('AUTOLARIS_TOTAL_MISMATCH','AUTOLARIS_AMOUNT_MISMATCH'))
    AND ("app"."autolaris_payment"."refusal_code" IS NOT NULL OR ("app"."autolaris_payment"."provider_amount"="app"."autolaris_payment"."requested_amount" AND "app"."autolaris_payment"."provider_total"="app"."autolaris_payment"."requested_amount")))));--> statement-breakpoint
ALTER TABLE "app"."cod_remittance" ADD CONSTRAINT "cod_remittance_value_check" CHECK ("app"."cod_remittance"."environment" IN ('local','test','production') AND "app"."cod_remittance"."reference" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{2,79}$' AND "app"."cod_remittance"."gross_amount" between 1 and 9007199254740991 AND "app"."cod_remittance"."shipping_deduction">=0 AND "app"."cod_remittance"."cod_fee_deduction">=0 AND "app"."cod_remittance"."other_deduction">=0 AND "app"."cod_remittance"."net_amount" between 0 and 9007199254740991 AND char_length("app"."cod_remittance"."evidence") between 1 and 500 AND char_length("app"."cod_remittance"."reason") between 1 and 200);--> statement-breakpoint
ALTER TABLE "app"."economic_receipt" ADD CONSTRAINT "economic_receipt_identity_check" CHECK ("app"."economic_receipt"."environment" IN ('local','test','production') AND "app"."economic_receipt"."event_id" ~ '^[A-Za-z0-9_.:-]{1,200}$' AND "app"."economic_receipt"."effect_reference" ~ '^[A-Za-z0-9_.:-]{1,200}$');--> statement-breakpoint
ALTER TABLE "app"."finance_transaction" ADD CONSTRAINT "finance_transaction_identity_check" CHECK ("app"."finance_transaction"."source" ~ '^[a-z][a-z0-9_.-]{0,99}$' AND "app"."finance_transaction"."environment" IN ('local','test','production') AND "app"."finance_transaction"."effect_reference" ~ '^[A-Za-z0-9_.:-]{1,200}$' AND "app"."finance_transaction"."request_hash" ~ '^[0-9a-f]{64}$' AND char_length("app"."finance_transaction"."reason") between 1 and 500);--> statement-breakpoint
ALTER TABLE "app"."local_cod_operation" ADD CONSTRAINT "local_cod_operation_value_check" CHECK ("app"."local_cod_operation"."environment" IN ('local','test','production') AND "app"."local_cod_operation"."reference" ~ '^[A-Za-z0-9_.:-]{1,200}$' AND "app"."local_cod_operation"."requested_amount" between 0 and 9007199254740991 AND (("app"."local_cod_operation"."status"='collected' AND "app"."local_cod_operation"."amount" between 1 and 9007199254740991) OR ("app"."local_cod_operation"."status"='refused' AND "app"."local_cod_operation"."amount"=0)));--> statement-breakpoint
ALTER TABLE "app"."local_parcel_receipt" ADD CONSTRAINT "local_parcel_receipt_value_check" CHECK ("app"."local_parcel_receipt"."environment" IN ('local','test','production') AND "app"."local_parcel_receipt"."reference" ~ '^[A-Za-z0-9_.:-]{1,200}$' AND "app"."local_parcel_receipt"."request_hash" ~ '^[a-f0-9]{64}$' AND "app"."local_parcel_receipt"."signature" ~ '^[a-f0-9]{64}$' AND jsonb_typeof("app"."local_parcel_receipt"."unit_ids")='array' AND jsonb_array_length("app"."local_parcel_receipt"."unit_ids") between 1 and 100);--> statement-breakpoint
ALTER TABLE "app"."local_payment_operation" ADD CONSTRAINT "local_payment_operation_profile_check" CHECK ("app"."local_payment_operation"."environment" IN ('local','test','production') AND "app"."local_payment_operation"."status" IN ('pending','confirmed','expired','failed'));--> statement-breakpoint
ALTER TABLE "app"."local_settlement_operation" ADD CONSTRAINT "local_settlement_operation_value_check" CHECK ("app"."local_settlement_operation"."provider" IN ('local.payment','local.cod') AND "app"."local_settlement_operation"."environment" IN ('local','test','production') AND "app"."local_settlement_operation"."reference" ~ '^[A-Za-z0-9_.:-]{1,200}$' AND "app"."local_settlement_operation"."direction" IN ('credit','debit') AND "app"."local_settlement_operation"."net_amount" between 0 and 9007199254740991 AND "app"."local_settlement_operation"."request_hash" ~ '^[0-9a-f]{64}$');